INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0602', 1, 'KP0601', '简答', '以例6.1 Student(Sno,School,Mname,Cno,Grade) 为例，说明不良模式会产生哪些异常，并写出一种分解思路。', NULL, '该模式存在数据冗余（院长姓名重复）、更新异常（换院长要改多条）、插入异常（新学院无学生无法存入）、删除异常（学生毕业删记录会丢失学院与院长信息）。原因是函数依赖存在不良性质；可分解为 S(Sno,School)、SC(Sno,Cno,Grade)、SCHOOL(School,Mname)，分别保留 Sno→School、(Sno,Cno)→Grade、School→Mname。', '四种异常要逐一对应例6.1的语义，不能只写“冗余”。分解的依据是把传递依赖 School→Mname 与部分依赖 Sno→School 从原模式中分离，使每个新模式只保留必要的函数依赖。', '2', '教材 P172—173；例6.1', '可换成“学院/学生/课程”的其他语义再练。')
