INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0603', 1, 'KP0602', '单选', '函数依赖 X→Y 成立的含义是（ ）。', '[{"key":"A","text":"对 R 的任一关系，任意两元组在 X 上值相等则在 Y 上值也相等"},{"key":"B","text":"对 R 的某一关系，存在两元组在 X 上值相等而 Y 上不等"},{"key":"C","text":"X 的值一定小于 Y 的值"},{"key":"D","text":"Y 的值可以决定 X 的值"}]', 'A', '函数依赖要求 R 的所有可能关系都满足：X 值相同则 Y 值必相同；只要存在一个关系实例违反就不成立。它是语义约束，不是数值大小关系，也不表示反向决定。', '1', '教材 P174', '可给一个违反 FD 的具体表让学生判断。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0604', 1, 'KP0602', '多选', '关于函数依赖，下列说法正确的有（ ）。', '[{"key":"A","text":"X→Y 且 Y⊄X 为非平凡函数依赖"},{"key":"B","text":"X→Y 且 X 的任何真子集都不能决定 Y，则 Y 完全函数依赖于 X"},{"key":"C","text":"X→Y、Y→Z 且满足传递依赖条件时，Z 传递函数依赖于 X"},{"key":"D","text":"X→Y 且 Y⊆X 表示 X 部分函数依赖于 Y"}]', 'ABC', 'A 是非平凡定义；B 是完全函数依赖定义；C 是传递函数依赖定义。D 错：Y⊆X 时 X→Y 是平凡函数依赖，不是部分依赖；部分依赖讨论的是 X 的真子集能否决定 Y。', '2', '教材 P174—175', '可把完全/部分/传递做成三道判断。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0605', 1, 'KP0602', '填空', 'X→Y 且 Y⊄X 称为______；X 称为该函数依赖的______；X→Y 且 X 的任何真子集都不能决定 Y，称为______；X→Y、Y→Z 且满足附加条件时，称为______。', NULL, '非平凡函数依赖；决定因素；完全函数依赖；传递函数依赖', '四个空对应函数依赖的四个基本术语。注意平凡/非平凡看 Y 是否被 X 包含；决定因素是左部；完全依赖看真子集；传递依赖还要满足 Y⊄X、Y≠X、Z⊄Y 等条件。', '2', '教材 P174—175', '可把“平凡”与“非平凡”互换出题。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0606', 1, 'KP0603', '单选', '设 K 为 R(U,F) 的属性或属性组，K 成为候选码的条件是（ ）。', '[{"key":"A","text":"K→U"},{"key":"B","text":"U→K"},{"key":"C","text":"K→Y 且 Y⊂U"},{"key":"D","text":"K 是单个属性"}]', 'A', '候选码定义是 K→U；若 U 部分函数依赖于 K，则 K 只是超码。候选码可以是单个属性，也可以是属性组，全码是极端情况。', '1', '教材 P176', '可问“候选码与超码的区别”。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0607', 1, 'KP0603', '综合', '给定 R(U,F)，U={A,B,C,D,E}，F={B→D, DE→C, EC→B}。求 R 的所有候选码，并指出主属性与非主属性。', NULL, 'N={A}，L={E}，LR={B,C,D}，R=∅。候选码必须包含 A、E，迭代枚举 LR 中属性，得到 (AEB)+=(AEC)+=(AED)+=ABCDE，所以候选码为 AEB、AEC、AED；A、B、C、D、E 都是主属性，无非主属性。', '求码用“N/L/R/LR”分类法：只出现在左部的属性和未出现的属性必在码中，只出现在右部的属性必不在码中；再枚举 LR 属性求闭包。本题 A 未出现、E 只在左部，故码必含 AE，逐个加 B/C/D 即得三个候选码。', '3', '习题 6 第 4 题；习题册 P73', '可改一个 FD 让候选码数量变化。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0608', 1, 'KP0604', '单选', '关系模式 R 属于 2NF 的条件是（ ）。', '[{"key":"A","text":"R 的每个分量不可分"},{"key":"B","text":"R 的每个非主属性都完全函数依赖于任一候选码"},{"key":"C","text":"R 的每个属性都完全函数依赖于主码"},{"key":"D","text":"R 中不存在传递函数依赖"}]', 'B', '2NF 在 1NF 基础上要求每个非主属性完全函数依赖于任一候选码；A 只是 1NF，C 把主属性也纳入要求（2NF 不要求主属性），D 是 3NF 的典型特征之一。', '1', '教材 P177', '可把 2NF/3NF 定义做成对比题。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0609', 1, 'KP0604', '简答', '关系模式 S-L-C(Sno,School,Sloc,Cno,Grade)，码为 (Sno,Cno)。说明它为什么不是 2NF，会产生哪些问题，如何分解为 2NF。', NULL, 'Sno→School、Sno→Sloc，而 Sno 是码 (Sno,Cno) 的真子集，所以 School、Sloc 部分函数依赖于码，S-L-C 不是 2NF。会产生插入异常（新生未选课无法插入）、删除异常（删除课程连带学生信息）、修改复杂（转学院要改多条）。分解为 SC(Sno,Cno,Grade) 与 S-L(Sno,School,Sloc)，两个新模式非主属性都对码完全函数依赖。', '判断 2NF 的关键是找非主属性是否部分依赖码；Sno 是复合码的真子集，能单独决定 School/Sloc，因此违约。分解要按依赖关系拆，而不是随意按属性个数拆。', '2', '教材 P177—178；例6.4', '可把码改成单属性再判断 2NF。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0610', 1, 'KP0604', '综合', '关系模式 R(员工编号,日期,零件数,部门名称,部门经理)，语义：每个员工每天只有一个零件数，每个员工只在一个部门，每个部门只有一个经理。写出基本函数依赖与码，判断是否 2NF，并分解到 2NF、3NF。', NULL, 'F={(员工编号,日期)→零件数, 员工编号→部门名称, 部门名称→部门经理}；码=(员工编号,日期)。R 不是 2NF，因为员工编号→部门名称，部门名称部分依赖于码。2NF 分解：R1(员工编号,日期,零件数)、R2(员工编号,部门名称,部门经理)。3NF 再分解：R1(员工编号,日期,零件数)、R2(员工编号,部门名称)、R3(部门名称,部门经理)。', '先由语义写 FD，再由“必含属性+闭包”确定码。2NF 检查复合码的真子集是否决定非主属性；3NF 再把 R2 中的传递依赖 员工编号→部门名称→部门经理 拆开。分解顺序体现 2NF→3NF 的递进。', '3', '习题册第6章补充 第5题；习题册 P80', '可把“部门经理”改为“部门电话”再练一次。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0611', 1, 'KP0605', '单选', '3NF 要求关系模式中（ ）。', '[{"key":"A","text":"不存在非主属性对码的部分依赖和传递依赖"},{"key":"B","text":"不存在任何函数依赖"},{"key":"C","text":"所有属性都必须单独成码"},{"key":"D","text":"只允许单属性码"}]', 'A', '3NF 在 2NF 基础上进一步排除非主属性对码的传递依赖；等价说法是非主属性既不部分依赖也不传递依赖于码。它不要求没有函数依赖，也不要求单属性码。', '1', '教材 P178', '可问“3NF 是否允许主属性传递依赖”。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0612', 1, 'KP0605', '简答', '说明 3NF 与 2NF 的关系，并以 S-L(Sno,School,Sloc)、Sno→School、School→Sloc 为例说明如何消除传递依赖。', NULL, '3NF 一定 2NF，但 2NF 不一定 3NF；3NF 在 2NF 基础上排除非主属性对码的传递依赖。S-L 中 Sno→School、School→Sloc，Sloc 传递依赖于码 Sno，故 S-L 不是 3NF。分解为 S-SS(Sno,School) 与 S-SL(School,Sloc) 后，两个新模式都不再含传递依赖，均为 3NF。', '关系是“3NF⊂2NF”：3NF 条件更强。消除传递依赖的办法是把中间决定因素 School 单独成表，使 School→Sloc 在新表中成为直接依赖，而不是跨表的传递链。', '2', '教材 P178—179', '可让学生判断分解后是否仍保持函数依赖。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0613', 1, 'KP0606', '单选', '关系模式 R 属于 BCNF 的条件是（ ）。', '[{"key":"A","text":"每个非主属性都完全依赖码"},{"key":"B","text":"每个决定因素都包含码"},{"key":"C","text":"每个属性都包含码"},{"key":"D","text":"不存在多值依赖"}]', 'B', 'BCNF 要求对 X→Y 且 Y⊄X，X 必含码，即每个决定因素都包含码。A 只是 2NF/3NF 的一部分；C 过强；D 是 4NF 关注的多值依赖，不是 BCNF 定义。', '1', '教材 P179', '可把“决定因素”与“右部”互换出题。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0614', 1, 'KP0606', '多选', '关于 3NF 与 BCNF，下列说法正确的有（ ）。', '[{"key":"A","text":"BCNF 一定属于 3NF"},{"key":"B","text":"3NF 不一定属于 BCNF"},{"key":"C","text":"STJ(S,T,J) 是 3NF 但不是 BCNF"},{"key":"D","text":"3NF 一定属于 BCNF"}]', 'ABC', 'BCNF 条件更强，故 BCNF⊂3NF；反向不成立，STJ 中 T→J 的决定因素 T 不含码，是 3NF 非 BCNF 的经典反例。D 与 B 矛盾，错误。', '2', '教材 P179—180；例6.8', '可让学生自己构造一个 3NF 非 BCNF 的例子。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0615', 1, 'KP0606', '简答', '关系模式 STJ(S,T,J)，F={(S,J)→T,(S,T)→J,T→J}。说明它为什么是 3NF 但不是 BCNF，并给出一个 BCNF 分解。', NULL, 'STJ 的候选码是 (S,J)、(S,T)，所有属性都是主属性，没有非主属性对码的部分/传递依赖，所以是 3NF。但 T→J 的决定因素 T 不含码，违反 BCNF 的“每个决定因素含码”，所以不是 BCNF。可分解为 ST(S,T) 与 TJ(T,J)，二者均为 BCNF。', '判断 BCNF 要看所有决定因素，不能只看非主属性；STJ 的“问题”正是主属性 T 作为决定因素却不含码。分解把 T→J 单独成表，消除非码决定因素。', '3', '教材 P180；例6.8', '可问分解后是否保持函数依赖。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0616', 1, 'KP0607', '单选', '关系模式 R 属于 4NF 的条件是（ ）。', '[{"key":"A","text":"所有函数依赖左部都含码"},{"key":"B","text":"对每个非平凡且非函数依赖的多值依赖 X→→Y，X 都含有码"},{"key":"C","text":"不存在任何多值依赖"},{"key":"D","text":"所有属性都是主属性"}]', 'B', '4NF 在 BCNF 基础上处理多值依赖：只要求非平凡且非函数依赖的 MVD 左部含码；平凡 MVD 和由 FD 派生的 MVD 不受此限。A 是 BCNF 的函数依赖版本，C/D 都过强或无关。', '1', '教材 P180—184', '可把 4NF 与 BCNF 条件做成对比。')
