INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0618', 1, 'KP0607', '综合', '关系模式 Teaching(C,T,B)，C 为课程、T 为教师、B 为参考书；每门课有多个教师、多本参考书，教师与参考书相互独立。说明它的码、最高范式与存在的问题，并分解为 4NF。', NULL, '码为全码 (C,T,B)，Teaching 属于 BCNF；但存在 C→→T、C→→B 两个非平凡且非函数依赖的多值依赖，增删教师或参考书要动多个元组，冗余明显。分解为 CT(C,T) 与 CB(C,B)，两个模式中 MVD 变为平凡 MVD，均属于 4NF。', '全码模式常被误认为“最规范”，但 BCNF 只处理函数依赖，管不住多值依赖。C→→T 表示课程决定一组教师，与参考书无关；把两组独立信息拆成 CT、CB 即可消除非平凡 MVD。', '3', '教材 P180—184；例6.9', '可换成 WSC(仓库,保管员,商品) 再练一次。')
