INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0619', 1, 'KP0608', '单选', 'Armstrong 公理系统的三条基本推理规则是（ ）。', '[{"key":"A","text":"自反律、增广律、传递律"},{"key":"B","text":"合并律、分解律、伪传递律"},{"key":"C","text":"自反律、合并律、分解律"},{"key":"D","text":"增广律、伪传递律、传递律"}]', 'A', 'Armstrong 公理系统由 A1 自反律、A2 增广律、A3 传递律组成；合并、伪传递、分解是由这三条推导出的有用规则，不是公理本身。', '1', '教材 P185', '可把公理与派生规则混在一起做多选题。')
