INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0621', 1, 'KP0608', '简答', '已知 U={A,B,C,D,E}，F={AB→C, B→D, C→E, EC→B, AC→B}，求 (AB)+，并判断 AB 是否为候选码。', NULL, '(AB)+：初始 AB；由 AB→C 得 ABC；由 B→D 得 ABCD；由 C→E 得 ABCDE。因 (AB)+=U，所以 AB 是候选码。', '闭包算法从 X 出发，反复扫描 F，把左部被当前集合包含的依赖的右部并入，直到集合不再变化。本题两步即可扩展到全属性集，故 AB→U，AB 为候选码。', '3', '教材 P187；例6.11', '可去掉 AB→C 再判断 AB 是否仍为码。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0622', 1, 'KP0609', '单选', '关于最小依赖集（最小覆盖），下列说法正确的是（ ）。', '[{"key":"A","text":"最小依赖集一定唯一"},{"key":"B","text":"最小依赖集要求每个函数依赖右部只含一个属性，且左部无冗余、整体无冗余依赖"},{"key":"C","text":"最小依赖集就是原依赖集去掉重复项"},{"key":"D","text":"最小依赖集一定保持无损连接"}]', 'B', '最小依赖集三条件：右部单属性、删除任一依赖不等价、左部无冗余属性；它不唯一（与处理顺序有关），也不是简单去重，更不直接保证无损连接。', '2', '教材 P188', '可给一个小 F 让学生求两个不同的最小覆盖。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0623', 1, 'KP0609', '简答', '写出求最小依赖集的三步，并说明算法6.2（合成法）如何得到保持函数依赖的 3NF 分解。', NULL, '三步：①把每个 X→Y 且 Y 含多属性拆成 X→A；②若去掉 X→A 后 F 仍等价，则删除该依赖；③对左部 X 的每个属性 B，若去掉 B 后 F 仍等价，则用 X-B 替换 X。合成法：先极小化 F；把不出现在 F 中的属性单独成 R0；按相同左部把依赖分组，每组属性构成一个子模式；得到保持函数依赖的 3NF 分解。', '极小化三步分别处理“右部多属性、整体冗余依赖、左部冗余属性”；合成法按左部分组，保证每个子模式的投影依赖都保留，因此 F+ 不丢。注意最小依赖集不唯一，但结果都等价。', '3', '教材 P188—189', '可给一个 F 让学生实际跑三步。')
