INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0624', 1, 'KP0610', '单选', '分解 ρ 具有无损连接性的含义是（ ）。', '[{"key":"A","text":"分解后不丢失任何属性"},{"key":"B","text":"对原模式的任一关系 r，都有 r = mρ(r)"},{"key":"C","text":"分解后每个子模式都达到 3NF"},{"key":"D","text":"分解后函数依赖集不变"}]', 'B', '无损连接指投影再自然连接能恢复原关系，即 r=mρ(r) 对任一 r 成立；不丢属性只是分解的基本要求，范式与保持 FD 是另外的准则。', '2', '教材 P191—192', '可把无损连接与保持 FD 做成对比。')
ON DUPLICATE KEY UPDATE primary_kp_id = VALUES(primary_kp_id), question_type = VALUES(question_type), question_text = VALUES(question_text), options_json = VALUES(options_json), answer_text = VALUES(answer_text), analysis_text = VALUES(analysis_text), difficulty = VALUES(difficulty), source = VALUES(source), variant_hint = VALUES(variant_hint);

INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0625', 1, 'KP0610', '简答', '写出判别一个分解是否无损连接的表算法步骤，并说明无损连接与保持函数依赖是不是同一准则。', NULL, '①建 k 行 n 列表，属性属于子模式填 aj，否则填 bij；②对每个 FD X→A，找 X 列相同符号的行，若某行 A 列为 aj 则全改 aj，否则全改 bmj；③重复扫描直到表不变；④若出现一行全为 a，则无损，否则不是。无损连接与保持函数依赖是两种不同准则，有的分解只满足其一，有的可同时满足。', '表算法的关键是“按 FD 逐步改符号”，直到不动点；不能只扫一遍。无损连接保证“能恢复数据”，保持 FD 保证“依赖不丢”，二者目标不同，不能互相替代。', '3', '教材 P192—193；例6.15', '可给一个 3 子模式分解让学生画表。')
